export function lightmapBakeDialog(document,{path,objects,run,error}){
 const dialog=document.createElement('dialog');dialog.className='close-document-dialog';const heading=document.createElement('h2');heading.textContent='간접광 베이크';const form=document.createElement('form');const field=(name,label,type,value,min,max)=>{const row=document.createElement('label');row.textContent=label;const input=document.createElement('input');input.type=type;input.name=name;input.value=value;if(min!==undefined)input.min=min;if(max!==undefined)input.max=max;input.required=true;input.dataset.lightmapBakeField=name;row.append(input);form.append(row);};field('path','라이트맵','text',path);field('resolution','수신 메시 해상도','number',128,16,2048);field('samples','샘플','number',32,1,4096);field('bounces','반사 횟수','number',1,1,8);const output=document.createElement('output');output.textContent=objects.length+' 오브젝트';const footer=document.createElement('footer'),cancel=document.createElement('button'),start=document.createElement('button');cancel.type='button';cancel.textContent='취소';start.type='submit';start.className='primary-button';start.textContent='베이크 저장';start.dataset.lightmapBakeStart='';footer.append(cancel,start);form.append(output,footer);dialog.append(heading,form);document.body.append(dialog);let job;cancel.onclick=()=>{job?.abort();dialog.close();};dialog.oncancel=()=>job?.abort();dialog.onclose=()=>{job?.abort();dialog.remove();};form.onsubmit=async event=>{event.preventDefault();if(job)return;job=new AbortController();start.disabled=true;for(const input of form.querySelectorAll('input'))input.disabled=true;const values=Object.fromEntries([...form.querySelectorAll('input')].map(input=>[input.name,input.value]));try{await run({ownerDialog:dialog,targetPath:values.path,objects,settings:{resolution:Number(values.resolution),samples:Number(values.samples),bounces:Number(values.bounces)},signal:job.signal,onProgress:p=>{if(p.phase==='save'){output.textContent='저장 중';cancel.disabled=true;return;}output.textContent=(p.mesh+1)+' / '+p.total+' · '+Math.round(p.triangle/p.triangles*100)+'%';}});dialog.close();}catch(e){if(!job.signal.aborted)error(e.message);if(dialog.isConnected){cancel.disabled=false;start.disabled=false;for(const input of form.querySelectorAll('input'))input.disabled=false;job=null;}}};dialog.show();return dialog;
}
